import{_ as o,o as s,c as a,a2 as t}from"./chunks/framework.B_GyVC5q.js";const g=JSON.parse('{"title":"Mobile apps","description":"","frontmatter":{"title":"Mobile apps"},"headers":[],"relativePath":"guide/mobile.md","filePath":"guide/mobile.md"}'),n={name:"guide/mobile.md"};function r(i,e,l,p,d,c){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="mobile-apps" tabindex="-1">Mobile apps <a class="header-anchor" href="#mobile-apps" aria-label="Permalink to &quot;Mobile apps&quot;">​</a></h1><p>Data Explorer is also available as native <strong>iOS</strong> and <strong>Android</strong> apps (Tauri). You connect to a 4D REST server from the <strong>Connection screen</strong>; browsing, query, Console dock, Flows, HTTP Client, and REST Export use the same named parts as the web app, adapted for touch. See <a href="/4d-dataexplorer/guide/parts.html#mobile-dock">Anatomy</a>.</p><h3 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h3><ul><li>Connection profiles with optional TLS skip for local/dev servers</li><li>Safe-area aware chrome; <strong>Mobile dock</strong> (Console / Terminal) as a full-screen overlay</li><li>Share / save downloads via the system share sheet (iOS) or Downloads (Android)</li><li>Touch-sized controls in the ORDA Terminal composer (REPL / Code, Run, snippet tabs)</li><li><strong>Sign in</strong> on the connection URL copies a 4D browser session via <code>dataexplorer://copy-session</code></li></ul><p>Desktop and web docs in this guide apply unless noted as desktop-only (window menus, auto-updater) or web-only (Docker hosting).</p><h2 id="copy-a-browser-session" tabindex="-1">Copy a browser session <a class="header-anchor" href="#copy-a-browser-session" aria-label="Permalink to &quot;Copy a browser session&quot;">​</a></h2><p>On the connection form, fill the <strong>Server URL</strong> then tap <strong>Sign in</strong>. The app opens <code>/rest/$singleton/CopySession/copySession</code> in the system browser. After you confirm, the page returns to Data Explorer through the <code>dataexplorer://copy-session</code> deep link and fills the connection cookies.</p><p>Add the <code>CopySession</code> shared singleton class to your 4D project (use <strong>Download CopySession class</strong> from the Sign in menu). Keep <code>dataexplorer://*</code> in the class’s trusted URL list.</p><hr>',9)])])}const u=o(n,[["render",r]]);export{g as __pageData,u as default};
